/**
 * API Reference Loader
 * 
 * Enterprise-grade loader for API documentation generated by TypeDoc.
 * Provides utilities for loading, parsing, searching, and navigating API symbols.
 * 
 * @packageDocumentation
 */

import fs from 'fs/promises'
import path from 'path'
import matter from 'gray-matter'

// ============================================================================
// Path Configuration
// ============================================================================

const WORKSPACE_ROOT = path.join(process.cwd(), '..')
const API_CONTENT_PATH = path.join(WORKSPACE_ROOT, 'docs/content/api')
const API_REFERENCE_PATH = path.join(WORKSPACE_ROOT, 'docs/api-reference')
const PACKAGES_PATH = path.join(WORKSPACE_ROOT, 'packages')

// ============================================================================
// Type Definitions
// ============================================================================

export type ApiSymbolKind = 
  | 'module'
  | 'namespace'
  | 'class'
  | 'interface'
  | 'type'
  | 'function'
  | 'variable'
  | 'enum'
  | 'enumMember'
  | 'method'
  | 'property'
  | 'constructor'
  | 'accessor'
  | 'getSignature'
  | 'setSignature'
  | 'callSignature'
  | 'indexSignature'

export interface ApiParameter {
  name: string
  type: string
  description?: string
  optional: boolean
  defaultValue?: string
  rest?: boolean
}

export interface ApiTypeParameter {
  name: string
  constraint?: string
  default?: string
  description?: string
}

export interface ApiSymbol {
  id: string
  name: string
  kind: ApiSymbolKind
  package: string
  module?: string
  signature?: string
  description?: string
  parameters?: ApiParameter[]
  typeParameters?: ApiTypeParameter[]
  returnType?: string
  returnDescription?: string
  examples?: string[]
  tags?: Record<string, string>
  sourceFile?: string
  sourceLine?: number
  deprecated?: string | boolean
  since?: string
  see?: string[]
  throws?: Array<{ type: string; description: string }>
  inherits?: string
  implements?: string[]
  members?: ApiSymbol[]
}

export interface ApiPackageInfo {
  name: string
  displayName: string
  version: string
  description: string
  category: string
  keywords: string[]
  repository?: string
  license?: string
  dependencies?: Record<string, string>
  peerDependencies?: Record<string, string>
  exports: string[]
  entryPoints: string[]
  symbolCount: number
}

export interface ApiDocPage {
  slug: string
  title: string
  description: string
  package: string
  category: string
  content: string
  toc: TocItem[]
  symbols: ApiSymbol[]
  metadata: Record<string, unknown>
  lastModified?: string
}

export interface TocItem {
  id: string
  title: string
  level: number
  children?: TocItem[]
}

export interface ApiCategory {
  id: string
  name: string
  slug: string
  description: string
  icon: string
  packages: ApiPackageInfo[]
  order: number
}

export interface ApiSearchResult {
  symbol: ApiSymbol
  score: number
  highlights: {
    field: string
    matches: string[]
  }[]
}

