export async function getAllApiPackages(): Promise<ApiPackageInfo[]> {
  return discoverPackages()
}

export async function getApiPackagesByCategory(): Promise<ApiCategory[]> {
  const packages = await discoverPackages()
  const categoryMap = new Map<string, ApiCategory>()
  
  for (const pkg of packages) {
    const categoryConfig = API_CATEGORIES[pkg.category]
    if (!categoryConfig) continue
    
    if (!categoryMap.has(pkg.category)) {
      categoryMap.set(pkg.category, {
        ...categoryConfig,
        packages: [],
      })
    }
    
    categoryMap.get(pkg.category)!.packages.push(pkg)
  }
  
  return Array.from(categoryMap.values())
    .sort((a, b) => a.order - b.order)
}

export async function getApiPackage(name: string): Promise<ApiPackageInfo | null> {
  const packages = await discoverPackages()
  return packages.find(p => p.name === name || p.displayName === name) || null
}

// ============================================================================
// Navigation
// ============================================================================

export interface ApiNavItem {
  title: string
  href: string
  description?: string
  badge?: string
  icon?: string
  items?: ApiNavItem[]
}

export async function getApiNavigation(): Promise<ApiNavItem[]> {
  const categories = await getApiPackagesByCategory()
  
  return categories.map(category => ({
    title: category.name,
    href: `/docs/api/${category.slug}`,
    description: category.description,
    icon: category.icon,
    badge: `${category.packages.length}`,
    items: category.packages.map(pkg => ({
      title: pkg.displayName,
      href: `/docs/api/${pkg.displayName.toLowerCase().replace(/[^a-z0-9]+/g, '-')}`,
      description: pkg.description,
    })),
  }))
}

// ============================================================================
// Statistics
// ============================================================================

export interface ApiStats {
  totalPackages: number
  totalSymbols: number
  categoryCounts: Record<string, number>
  kindCounts: Record<string, number>
}

export async function getApiStats(): Promise<ApiStats> {
  const packages = await discoverPackages()
  const symbols = await getAllApiSymbols()
  
  const categoryCounts: Record<string, number> = {}
  for (const pkg of packages) {
    categoryCounts[pkg.category] = (categoryCounts[pkg.category] || 0) + 1
  }
  
  const kindCounts: Record<string, number> = {}
  for (const symbol of symbols) {
    kindCounts[symbol.kind] = (kindCounts[symbol.kind] || 0) + 1
  }
  
  return {
    totalPackages: packages.length,
    totalSymbols: symbols.length,
    categoryCounts,
    kindCounts,
  }
}
